      .skip-link {
        position: absolute;
        left: 1rem;
        top: 1rem;
        z-index: 10;
        transform: translateY(-150%);
        border-radius: 999px;
        padding: 0.75rem 1rem;
        color: #ffffff;
        background: var(--accent-strong);
        font-weight: 700;
        text-decoration: none;
      }

      .skip-link:focus {
        transform: translateY(0);
        outline: 3px solid #ffffff;
        outline-offset: 3px;
      }

      .page-shell {
        width: min(1120px, calc(100% - 2rem));
        margin: 0 auto;
        padding: 4rem 0;
