        display: grid;
        grid-template-columns: minmax(0, 1.35fr) minmax(17rem, 0.65fr);
        gap: 1.5rem;
        align-items: stretch;
        margin-bottom: 1.5rem;
      }

      .hero-copy,
      .care-card,
      .faq-card {
        border: 1px solid rgba(229, 216, 202, 0.82);
        background: rgba(255, 253, 248, 0.84);
        box-shadow: var(--shadow);
        backdrop-filter: blur(18px);
      }

      .hero-copy {
        border-radius: var(--radius-lg);
        padding: clamp(2rem, 5vw, 4rem);
      }

      .eyebrow {
        display: inline-flex;
        align-items: center;
        gap: 0.5rem;
        margin: 0 0 1rem;
        border-radius: 999px;
        padding: 0.45rem 0.85rem;
        color: var(--accent-strong);
        background: #f1dfce;
        font-size: 0.88rem;
        font-weight: 800;
        letter-spacing: 0.08em;
        text-transform: uppercase;
      }

      h1 {
        max-width: 11ch;
        margin: 0;
        font-size: clamp(3rem, 8vw, 6.75rem);
        line-height: 0.9;
        letter-spacing: -0.075em;
      }

      .hero-copy p {
        max-width: 42rem;
        margin: 1.5rem 0 0;
        color: var(--muted);
        font-size: clamp(1.06rem, 2vw, 1.25rem);
      }

      .care-card {
        display: flex;
        flex-direction: column;
        justify-content: space-between;
        min-height: 100%;
        border-radius: var(--radius-lg);
        padding: 1.5rem;
      }

      .cat-mark {
        display: grid;
        width: 5rem;
        height: 5rem;
        place-items: center;
        border-radius: 1.5rem;
        color: #ffffff;
        background: linear-gradient(135deg, var(--accent), #cf7f43);
        font-size: 2.5rem;
      }

      .care-card h2 {
        margin: 1.25rem 0 0.5rem;
        font-size: 1.35rem;
        line-height: 1.2;
      }

      .care-card p {
        margin: 0;
        color: var(--muted);
      }

      .care-stat {
        display: grid;
        gap: 0.15rem;
        margin-top: 1.5rem;
        border-top: 1px solid var(--border);
        padding-top: 1.25rem;
      }

      .care-stat strong {
        color: var(--accent-strong);
        font-size: 2rem;
        line-height: 1;
      }

      .care-stat span {
        color: var(--muted);
        font-weight: 650;
      }

      .faq-card {
        border-radius: var(--radius-lg);
        padding: clamp(1rem, 2vw, 1.5rem);
      }

      .faq-list {
        display: grid;
        gap: 0.9rem;
      }

      .example {
        overflow: clip;
        border: 1px solid var(--border);
        border-radius: var(--radius-md);
        background: var(--surface-strong);
        transition:
