          transform 160ms ease,
          box-shadow 160ms ease;
      }

      .example:has(.question-button:hover),
      .example:has(.question-button:focus-visible) {
        border-color: rgba(138, 79, 42, 0.52);
        box-shadow: 0 16px 38px rgba(76, 48, 28, 0.12);
        transform: translateY(-1px);
      }

      h3 {
        margin: 0;
      }

      .question-button {
        display: flex;
        width: 100%;
        min-height: 4.25rem;
        align-items: center;
        justify-content: space-between;
        gap: 1rem;
        border: 0;
        padding: 1.2rem 1.25rem;
        color: inherit;
        background: transparent;
        font: inherit;
        font-size: 1.08rem;
        font-weight: 800;
        text-align: left;
        cursor: pointer;
      }

      .question-button:focus {
        outline: none;
      }

      .question-button:focus-visible {
        outline: 3px solid var(--accent-strong);
        outline-offset: -6px;
      }

      .question-button::after {
        flex: 0 0 auto;
        width: 2rem;
        height: 2rem;
        border: 1px solid #d8bfa6;
        border-radius: 999px;
        color: var(--accent-strong);
        background: #fff5eb;
        content: "+";
        font-size: 1.35rem;
        font-weight: 900;
        line-height: 1.8rem;
        text-align: center;
      }

      .question-button[aria-expanded="true"]::after {
        content: "−";
      }

      .details {
        padding: 0 1.25rem 1.35rem;
        color: var(--muted);
      }

      .details p {
        max-width: 66ch;
        margin: 0;
      }

