  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <div id="root"></div>

    <script>
      const faqs = [
        {
          question: "Why do cats purr?",
          answer:
            "Cats often purr when they feel relaxed, but purring can also help them self-soothe when they are stressed or uncomfortable. Context matters: look at posture, appetite, and behavior alongside the sound."
        },
        {
          question: "How much sleep do cats need?",
          answer:
            "Most adult cats sleep around 12 to 16 hours a day, while kittens and senior cats may sleep even more. Short bursts of activity between naps are normal because cats are crepuscular hunters."
        },
        {
          question: "Should indoor cats still visit the vet?",
          answer:
            "Yes. Indoor cats need preventive care, dental checks, vaccines recommended by a veterinarian, and routine screenings. Regular visits can catch subtle health changes before they become serious."
        },
        {
          question: "What is the best way to introduce a new cat?",
          answer:
            "Go slowly. Start with separate rooms, scent swapping, and supervised short meetings. Reward calm behavior and give each cat its own food, water, litter, scratching, and resting spaces."
        },
        {
          question: "Why does my cat knead blankets or people?",
          answer:
            "Kneading is a common comfort behavior that begins in kittenhood. Many cats knead when they feel secure, are preparing a resting spot, or are showing social attachment."
        }
      ];

      const escapeHtml = (value) =>
        value.replace(/[&<>"']/g, (character) => {
          const entities = {
            "&": "&amp;",
            "<": "&lt;",
            ">": "&gt;",
            '"': "&quot;",
            "'": "&#39;"
          };
          return entities[character];
        });

      function FAQItem({ question, answer }, index) {
        const buttonId = `faq-button-${index + 1}`;
        const panelId = `faq-panel-${index + 1}`;

        return `
          <div class="example">
            <h3>
              <button
                class="question-button"
                id="${buttonId}"
                type="button"
                aria-expanded="true"
                aria-controls="${panelId}"
              >
                ${escapeHtml(question)}
              </button>
            </h3>
            <div class="details" id="${panelId}" aria-labelledby="${buttonId}">
              <p>${escapeHtml(answer)}</p>
            </div>
          </div>
        `;
      }

      function Hero() {
        return `
          <section class="hero" aria-labelledby="page-title">
            <div class="hero-copy">
              <p class="eyebrow">Cat care basics</p>
              <h1 id="page-title">Cat FAQ</h1>
              <p>
                Quick answers for common cat questions, from everyday behavior
                to healthy routines and gentle introductions.
              </p>
            </div>
            <div class="care-card" aria-labelledby="care-note-title">
              <div>
                <div class="cat-mark" aria-hidden="true">🐾</div>
                <h2 id="care-note-title">Small habits, happier cats</h2>
                <p>
                  Predictable meals, clean litter, enrichment, and quiet rest
                  spaces help cats feel secure at home.
                </p>
              </div>
              <div class="care-stat">
                <strong>12–16</strong>
                <span>hours of sleep is common for adult cats</span>
              </div>
            </div>
          </section>
        `;
      }

      function FAQList({ items }) {
        return `
          <section class="faq-card" aria-labelledby="faq-heading">
            <h2 id="faq-heading">Frequently asked questions</h2>
            <div class="faq-list">
              ${items.map(FAQItem).join("")}
            </div>
          </section>
        `;
      }

      function App() {
        return `
          <main id="main-content" class="page-shell">
            ${Hero()}
            ${FAQList({ items: faqs })}
            <footer>
              <p>For medical concerns, contact a veterinarian who knows your cat.</p>
            </footer>
          </main>
        `;
      }

      function initializeDisclosures() {
        document.querySelectorAll(".question-button").forEach((button) => {
          const panel = document.getElementById(button.getAttribute("aria-controls"));
          if (!panel) {
            return;
          }

          button.setAttribute("aria-expanded", "false");
          panel.hidden = true;

          button.addEventListener("click", () => {
            const isOpen = button.getAttribute("aria-expanded") === "true";
            button.setAttribute("aria-expanded", String(!isOpen));
            panel.hidden = isOpen;
          });

          button.addEventListener("keydown", (event) => {
            if (event.key === "Escape" && button.getAttribute("aria-expanded") === "true") {
              button.setAttribute("aria-expanded", "false");
              panel.hidden = true;
              button.focus();
            }
          });
        });
      }

      document.getElementById("root").innerHTML = App();
      initializeDisclosures();
    </script>
  </body>
</html>
